e When lOpening<0 Then -lOpening End); NumCell(Case When lOpening>0 Then lOpening End); NumCell(abs(lOpening)); htp.prn('</Row>');
    Declare lRun Number:=lOpening; Begin
      For r In (Select d.VoucherDate,v.VoucherNo,coalesce(pb.PartyBillNo,ao.BillNo,v.VoucherNo) Reference,nvl(v.ModuleCode,v.DocTypeCode) SourceType,substr(d.Narration,1,300) Narration,Case When d.Amount<0 Then -d.Amount Else 0 End Debit,Case When d.Amount>0 Then d.Amount Else 0 End Credit From VoucherDetail d Join Voucher v On v.Tno=d.Tno Left Join PBPass pp On v.ModuleCode='PBPASS' And pp.Tno=v.ModuleTno Left Join PurchaseBill pb On pb.Tno=pp.PurchaseBillTno Left Join AccountOpening ao On v.VoucherNo='OPENING' And ao.Tno=d.ModuleTno Where d.AccountCode=lParty And d.VoucherDate>=lFrom And d.VoucherDate<lTo+1 And (cast(null as varchar2(100)) Is Null Or cast(null as varchar2(100))=cast(null as varchar2(100))) And (null Is Null Or cast(null as varchar2(100))=null) And (:P923_COMPANY Is Null Or d.CompanyCode=:P923_COMPANY) And (:P923_LOCATION Is Null Or d.LocationCode=:P923_LOCATION) Order By d.VoucherDate,d.Tno,d.Sno) Loop
        lRun:=lRun+nvl(r.Credit,0)-nvl(r.Debit,0); htp.prn('<Row>'); TextCell(to_char(r.VoucherDate,'DD-MM-RRRR')); TextCell(r.VoucherNo); TextCell(r.Reference); TextCell(r.SourceType); TextCell(r.Narration); NumCell(r.Debit); NumCell(r.Credit); NumCell(abs(lRun)); htp.prn('</Row>');
      End Loop;
    End;
    htp.prn('<Row>'); TextCell('Closing balance','Total'); BlankCells(6,'Total'); NumCell(abs(lClosing),'Total'); htp.prn('</Row>'); SheetEnd;

    SheetStart('Pending Bills','Pending Supplier Bills',8);
    htp.prn('<Row>'); TextCell('Voucher','Header'); TextCell('Bill Reference','Header'); TextCell('Document Date','Header'); TextCell('Due Date','Header'); TextCell('Bill Amount (₹)','Header'); TextCell('Allocated (₹)','Header'); TextCell('Outstanding (₹)','Header'); TextCell('Days Overdue','Header'); htp.prn('</Row>');
    For r In (With Asof As (Select lTo D From dual),Alc As (Select a.DrVoucherTno Tno,a.DrVoucherSno Sno,-Sum(a.Amount) Amt From DrCrAllocation a Join Voucher dv On dv.Tno=a.DrVoucherTno Join Voucher cv On cv.Tno=a.CrVoucherTno Cross Join Asof Where dv.VoucherDate<=Asof.D And cv.VoucherDate<=Asof.D Group By a.DrVoucherTno,a.DrVoucherSno Union All Select a.CrVoucherTno,a.CrVoucherSno,Sum(a.Amount) From DrCrAllocation a Join Voucher dv On dv.Tno=a.DrVoucherTno Join Voucher cv On cv.Tno=a.CrVoucherTno Cross Join Asof Where dv.VoucherDate<=Asof.D And cv.VoucherDate<=Asof.D Group By a.CrVoucherTno,a.CrVoucherSno),Al As (Select Tno,Sno,Sum(Amt) Amt From Alc Group By Tno,Sno),Pt As (Select pp.Tno,coalesce(Max(pb.PartyBillDate),Max(pb.PurchaseBillDate)) DocDt,Max(pb.PurchaseBillDate)+coalesce(Max(po.CreditDays),Max(pty.CreditDays)) DueDt,Max(pb.PartyBillNo) BillNo From PBPass pp Join PurchaseBill pb On pb.Tno=pp.PurchaseBillTno Left Join PurchaseBillDetail pbd On pbd.Tno=pb.Tno Left Join PurchaseOrder po On po.Tno=pbd.PurchaseOrderTno Left Join Party pty On pty.PartyCode=pb.PartyCode Group By pp.Tno),Jt As (Select jp.Tno,coalesce(Max(jb.PartyBillDate),Max(jb.JobBillDate)) DocDt,Max(jb.JobBillDate)+nvl(Max(jo.CreditDays),0) DueDt From JBPass jp Join JobBill jb On jb.Tno=jp.JobBillTno Left Join JobOrder jo On jo.Tno=jb.JobOrderTno Group By jp.Tno) Select v.VoucherNo,coalesce(pt.BillNo,ao.BillNo,v.VoucherNo) BillRef,coalesce(pt.DocDt,jt.DocDt,ao.BillDate,d.VoucherDate) DocDate,coalesce(pt.DueDt,jt.DueDt,ao.BillDueDate) DueDate,d.Amount BillAmount,nvl(al.Amt,0) Allocated,d.Amount-nvl(al.Amt,0) Outstanding,Case When coalesce(pt.DueDt,jt.DueDt,ao.BillDueDate) Is Not Null Then Greatest(lTo-coalesce(pt.DueDt,jt.DueDt,ao.BillDueDate),0) End DaysOverdue From VoucherDetail d Join Voucher v On v.Tno=d.Tno Left Join Al al On al.Tno=d.Tno And al.Sno=d.Sno Left Join Pt pt On v.ModuleCode='PBPASS' And pt.Tno=v.ModuleTno Left Join Jt jt On v.Module

